<?php
declare(strict_types=1);
namespace App\Interface\Http\Catalog\Controller;
use App\Application\Catalog\DTO\Request\UploadSyllabusDocumentRequestDto;use App\Application\Catalog\Service\UploadSyllabusDocumentService;use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class SyllabusDocumentController { public function __construct(private readonly AuthService $auth,private readonly UploadSyllabusDocumentService $upload,private readonly ApiResponseFactory $responses){} public function upload(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,string $syllabusId):ResponseInterface{try{$user=$this->auth->currentUser($access);if(!in_array('ADMIN',$user->roles,true))throw new \LogicException();$file=$request->getUploadedFiles()['document']??null;if(!$file instanceof \Psr\Http\Message\UploadedFileInterface||$file->getError()!==UPLOAD_ERR_OK)throw new \InvalidArgumentException();$result=$this->upload->upload(new UploadSyllabusDocumentRequestDto($syllabusId,$file->getClientFilename()??'edital.pdf',$file->getClientMediaType()??'',$file->getStream()->getContents()));return $this->responses->success($response,['id'=>$result->id,'document_sha256'=>$result->documentSha256],(string)$request->getAttribute('request_id'));}catch(DomainException|UnavailableUserException|\InvalidArgumentException|\LogicException){return $this->responses->problem($response,'VALIDATION_FAILED','Nao foi possivel enviar o documento.',422,(string)$request->getAttribute('request_id'));}} }
